from pathlib import Path
p=Path('/mnt/data/v14_work')
app=(p/'app.js').read_text()
html=(p/'index.html').read_text()
css=(p/'styles.css').read_text()

# Remove boostRate from newly-created formulas and normalize old formulas without exposing it.
app=app.replace("function makeWork(name='Новое место',color='#5b5ce2'){return{id:uid(),name,color,formula:{type:'hour_percent',rate:250,boostRate:180,percent:3,fixed:0}}}",
"function makeWork(name='Новое место',color='#5b5ce2'){return{id:uid(),name,color,formula:{type:'hour_percent',rate:250,percent:3,fixed:0}}}")
app=app.replace("if(d.settings&&!d.works.length&&d.settings.rate){d.works=[{id:'legacy',name:'Основная работа',color:'#4f67df',formula:{type:'hour_percent',rate:+d.settings.rate||250,boostRate:+d.settings.boostRate||180,percent:3,fixed:0}}]}",
"if(d.settings&&!d.works.length&&d.settings.rate){d.works=[{id:'legacy',name:'Основная работа',color:'#4f67df',formula:{type:'hour_percent',rate:+d.settings.rate||250,percent:3,fixed:0}}]}")
# normalize formula fields
needle="const fallbackWork=d.works[0];"
repl="""d.works=d.works.map(w=>{w.formula=w.formula||{type:'hour_percent',rate:250,percent:3,fixed:0};w.formula.type=['hour_percent','hourly','percent','fixed'].includes(w.formula.type)?w.formula.type:'hour_percent';w.formula.rate=Number(w.formula.rate)||0;w.formula.percent=Number(w.formula.percent)||0;w.formula.fixed=Number(w.formula.fixed)||0;delete w.formula.boostRate;return w});\n  const fallbackWork=d.works[0];"""
app=app.replace(needle,repl,1)

# Replace calc with robust formula calculation. Keep legacy boost entries readable using old snapshots only.
start=app.index("function calc(")
end=app.index("function earningsOf", start)
new_calc="""function calc(v,w=work(v?.workId)){\n  if(!v||v.type==='off')return 0;\n  const f=v.formulaSnapshot||w?.formula||{},h=Number(v.hours)||0,c=(Number(v.cash)||0)+(Number(v.card)||0);\n  if(v.type==='boost')return h*(Number(f.boostRate)||Number(f.rate)||0);\n  if(f.type==='hourly')return h*(Number(f.rate)||0);\n  if(f.type==='percent')return c*(Number(f.percent)||0)/100;\n  if(f.type==='fixed')return Number(f.fixed)||0;\n  return h*(Number(f.rate)||0)+c*(Number(f.percent)||0)/100;\n}\n"""
app=app[:start]+new_calc+app[end:]

# Replace work editor functions with dynamic field visibility and no boost rate.
old="""function openWorkEditor(id=null){editingWorkId=id;const w=id?work(id):makeWork();document.getElementById('workModalTitle').textContent=id?'Изменить место':'Новое место';document.getElementById('workName').value=w.name;document.getElementById('workColor').value=w.color;document.getElementById('formulaType').value=w.formula.type;document.getElementById('formulaRate').value=w.formula.rate;document.getElementById('formulaBoostRate').value=w.formula.boostRate;document.getElementById('formulaPercent').value=w.formula.percent;document.getElementById('formulaFixed').value=w.formula.fixed;document.getElementById('deleteWorkBtn').classList.toggle('hidden',!id);document.getElementById('workModal').classList.remove('hidden')}\nfunction saveWork(){const name=document.getElementById('workName').value.trim()||'Без названия',f={type:document.getElementById('formulaType').value,rate:+document.getElementById('formulaRate').value||0,boostRate:+document.getElementById('formulaBoostRate').value||0,percent:+document.getElementById('formulaPercent').value||0,fixed:+document.getElementById('formulaFixed').value||0},color=document.getElementById('workColor').value;if(editingWorkId){Object.assign(work(editingWorkId),{name,color,formula:f})}else{const w={...makeWork(name,color),name,color,formula:f};data.works.push(w);data.activeWorkId=w.id}save();closeWorkModal();renderAll();toast('Место работы сохранено')}"""
new="""function updateFormulaFields(){\n  const type=document.getElementById('formulaType')?.value||'hour_percent';\n  document.getElementById('formulaRateField')?.classList.toggle('hidden',!['hour_percent','hourly'].includes(type));\n  document.getElementById('formulaPercentField')?.classList.toggle('hidden',!['hour_percent','percent'].includes(type));\n  document.getElementById('formulaFixedField')?.classList.toggle('hidden',type!=='fixed');\n}\nfunction openWorkEditor(id=null){editingWorkId=id;const w=id?work(id):makeWork();document.getElementById('workModalTitle').textContent=id?'Изменить место':'Новое место';document.getElementById('workName').value=w.name;document.getElementById('workColor').value=w.color;document.getElementById('formulaType').value=w.formula.type;document.getElementById('formulaRate').value=w.formula.rate??'';document.getElementById('formulaPercent').value=w.formula.percent??'';document.getElementById('formulaFixed').value=w.formula.fixed??'';document.getElementById('deleteWorkBtn').classList.toggle('hidden',!id);updateFormulaFields();document.getElementById('workModal').classList.remove('hidden')}\nfunction saveWork(){const name=document.getElementById('workName').value.trim()||'Без названия',type=document.getElementById('formulaType').value,f={type,rate:+document.getElementById('formulaRate').value||0,percent:+document.getElementById('formulaPercent').value||0,fixed:+document.getElementById('formulaFixed').value||0},color=document.getElementById('workColor').value;if(editingWorkId){Object.assign(work(editingWorkId),{name,color,formula:f})}else{const w={...makeWork(name,color),name,color,formula:f};data.works.push(w);data.activeWorkId=w.id}save();closeWorkModal();renderAll();toast('Место работы сохранено')}"""
if old not in app: print('old work editor not found')
app=app.replace(old,new)

# Replace stats with an isolated, defensive implementation that cannot leave the cards at zero if the chart has data.
start=app.index("function renderStats(){")
end=app.index("function renderWorkList", start)
new_stats="""function statsEntries(monthDate){\n  const prefix=`${monthDate.getFullYear()}-${String(monthDate.getMonth()+1).padStart(2,'0')}-`;\n  const out=[];\n  Object.keys(data.days||{}).forEach(date=>{\n    if(!date.startsWith(prefix))return;\n    normalizeDayEntries(data.days[date]).forEach(e=>{\n      if(!e||e.type==='off')return;\n      const w=work(e.workId);\n      let n=Number(e.earnings);\n      if(!Number.isFinite(n)||n<0)n=Number(calc(e,w))||0;\n      const revenue=(Number(e.cash)||0)+(Number(e.card)||0);\n      out.push({date,e,w,n,revenue,hours:Number(e.hours)||0});\n    });\n  });\n  return out;\n}\nfunction renderStats(){\n  try{\n    const title=document.getElementById('statsMonth');if(title)title.textContent=monthLabel(statsMonth);\n    const es=statsEntries(statsMonth),byDay={};\n    es.forEach(x=>{(byDay[x.date]??=[]).push(x)});\n    const vals=Object.entries(byDay).sort((a,b)=>a[0].localeCompare(b[0])).map(([date,list])=>({d:date,n:list.reduce((s,x)=>s+x.n,0),revenue:list.reduce((s,x)=>s+x.revenue,0),hours:list.reduce((s,x)=>s+x.hours,0)}));\n    const max=Math.max(1,...vals.map(x=>x.n));\n    const bars=document.getElementById('bars');\n    if(bars){\n      bars.innerHTML=vals.length?vals.map(x=>{const h=Math.max(4,(x.n/max)*100);return `<button class=\\\"bar-wrap\\\" data-stat-date=\\\"${x.d}\\\" type=\\\"button\\\" title=\\\"${dateObj(x.d).toLocaleDateString('ru-RU',{day:'numeric',month:'short'})}: ${money(x.n)}\\\"><span class=\\\"bar-value\\\">${money(x.n)}</span><span class=\\\"bar\\\" style=\\\"height:${h}%\\\"></span><small>${dateObj(x.d).getDate()}</small></button>`}).join(''):'<div style=\\\"color:#999;margin:auto\\\">Нет данных за этот месяц</div>';\n      bars.querySelectorAll('[data-stat-date]').forEach(b=>b.onclick=()=>{const x=vals.find(v=>v.d===b.dataset.statDate);if(x)toast(`${dateObj(x.d).toLocaleDateString('ru-RU',{day:'numeric',month:'long'})}: ${money(x.n)} · выручка ${money(x.revenue)}`)});\n    }\n    const total=vals.reduce((s,x)=>s+x.n,0);\n    const hours=vals.reduce((s,x)=>s+x.hours,0);\n    const days=vals.length;\n    const best=vals.length?vals.reduce((a,b)=>b.n>a.n?b:a):null;\n    const commission=es.reduce((s,x)=>{const f=x.e.formulaSnapshot||x.w?.formula||{};return s+((x.revenue)*(Number(f.type==='hour_percent'||f.type==='percent'?f.percent:0)||0)/100)},0);\n    const set=(id,value)=>{const el=document.getElementById(id);if(el)el.textContent=value};\n    set('bestDay',best?`${dateObj(best.d).toLocaleDateString('ru-RU',{day:'numeric',month:'long'})} · ${money(best.n)}`:'—');\n    set('bestDayLabel',best?money(best.n):'—');\n    set('avgShift',money(days?total/days:0));\n    set('avgHour',money(hours?total/hours:0));\n    set('commissionTotal',money(commission));\n    const wb=document.getElementById('statsWorkBreakdown');\n    if(wb){const map={};es.forEach(x=>map[x.w?.id]=(map[x.w?.id]||0)+x.n);wb.innerHTML=Object.entries(map).sort((a,b)=>b[1]-a[1]).map(([id,n])=>{const w=work(id);return `<div class=\\\"break-row\\\"><i style=\\\"background:${w?.color||'#777'}\\\"></i><span>${escapeHtml(w?.name||'Работа')}</span><b>${money(n)}</b></div>`}).join('')||'<div class=\\\"muted\\\">Нет данных</div>'}\n  }catch(err){\n    console.error('Stats render error',err);\n    const set=(id,value)=>{const el=document.getElementById(id);if(el)el.textContent=value};\n    set('bestDay','Ошибка расчёта');set('bestDayLabel','Ошибка');set('avgShift','0 ₽');set('avgHour','0 ₽');set('commissionTotal','0 ₽');\n  }\n}\n"""
app=app[:start]+new_stats+app[end:]

# Update event bindings: formula type change should update fields.
app=app.replace("document.getElementById('saveWorkBtn').onclick=saveWork;", "document.getElementById('saveWorkBtn').onclick=saveWork;document.getElementById('formulaType').onchange=updateFormulaFields;")
# Ensure theme class is applied to html too and meta theme color updated.
app=app.replace("function applyTheme(){document.body.classList.toggle('dark',data.settings.theme==='dark');const b=document.getElementById('themeToggle');if(b)b.textContent=data.settings.theme==='dark'?'☀️ Светлая тема':'🌙 Тёмная тема'}",
"function applyTheme(){const dark=data.settings.theme==='dark';document.documentElement.classList.toggle('dark',dark);document.body.classList.toggle('dark',dark);const meta=document.querySelector('meta[name=theme-color]');if(meta)meta.content=dark?'#11121a':'#5865e8';const b=document.getElementById('themeToggle');if(b)b.textContent=dark?'☀️ Светлая тема':'🌙 Тёмная тема'}")
app=app.replace("const KEY='earnings_pwa_v14';", "const KEY='earnings_pwa_v15';")
app=app.replace("version:14", "version:15", 1)

# HTML: formula fields wrappers, remove boost field.
old_html='<label>Ставка за час <input id="formulaRate" type="number" inputmode="decimal" min="0"></label><label>Ставка усиления <input id="formulaBoostRate" type="number" inputmode="decimal" min="0"></label><label>Процент от выручки <input id="formulaPercent" type="number" inputmode="decimal" min="0" step="0.1"></label><label>Фикс за смену <input id="formulaFixed" type="number" inputmode="decimal" min="0"></label>'
new_html='<label id="formulaRateField">Ставка за час <input id="formulaRate" type="number" inputmode="decimal" min="0"></label><label id="formulaPercentField">Процент от выручки <input id="formulaPercent" type="number" inputmode="decimal" min="0" step="0.1"></label><label id="formulaFixedField">Фикс за смену <input id="formulaFixed" type="number" inputmode="decimal" min="0"></label>'
if old_html not in html: print('formula html not found')
html=html.replace(old_html,new_html)
html=html.replace('<meta name="theme-color" content="#5865e8">','<meta name="theme-color" content="#5865e8">')

# CSS dark theme: override app and all major light surfaces, plus form labels and formula editor.
css += """\n/* v15: complete dark theme */\nhtml.dark,html.dark body{background:#0e0f16;color:#f4f4fb}html.dark .app{background:linear-gradient(180deg,#151722,#0f1018);color:#f4f4fb}html.dark .topbar h1,html.dark .section-title h2,html.dark .block-title,html.dark label,html.dark .list-header,html.dark .day-date,html.dark .day-money,html.dark .work-row b{color:#f4f4fb}html.dark .eyebrow{color:#9b9cff}html.dark .work-select,html.dark .form-card,html.dark .list-card,html.dark .calendar-card,html.dark .note-card,html.dark .settings-block,html.dark .backup-card,html.dark .chart-card,html.dark .stats-detail,html.dark .stat-card,html.dark .goal-card,html.dark .forecast-card,html.dark .tabbar{background:#1a1c27;color:#f4f4fb;border-color:#303342;box-shadow:0 7px 25px #00000030}html.dark .work-select select,html.dark input,html.dark textarea,html.dark select{background:#11131b;color:#f4f4fb;border-color:#3a3c4d}html.dark input::placeholder,html.dark textarea::placeholder{color:#777a90}html.dark .work-select span,html.dark .muted,html.dark .hero-sub,html.dark .formula,html.dark .rate-preview,html.dark .section-title .month-nav,html.dark .stats-detail span,html.dark .stat-card span,html.dark .goal-card span,html.dark .forecast-card span,html.dark .forecast-card p,html.dark .day-type,html.dark .work-row small,html.dark .paint-hint,html.dark .legend,html.dark .note-card small,html.dark .list-header span{color:#aeb0c5}html.dark .icon-btn,html.dark .month-nav button,html.dark .secondary-btn,html.dark .calendar-tools .paint-btn,html.dark .goal-card button,html.dark .work-row button,html.dark .close-btn{background:#292c3b;color:#c3c5ff}html.dark .work-select button{background:#292c4a;color:#bfc2ff}html.dark .formula-box{background:#25283a;color:#c1c3d5}html.dark .progress{background:#303342}html.dark .cal-day{background:#20232f;color:#f4f4fb;border-color:#343746}html.dark .cal-day.off{background:#30323d}html.dark .cal-day .money{color:#b9bad0}html.dark .stats-detail div{background:#1a1c27}html.dark .day-row,html.dark .work-row{border-color:#303342}html.dark .tab{color:#a6a8bb}html.dark .tab.active{background:#2c2f50;color:#aeb1ff}html.dark .modal-sheet{background:#151722;color:#f4f4fb}html.dark .modal-backdrop{background:#000b}html.dark .modal-result{background:#292c47;color:#c5c7dc}html.dark .toast{background:#f1f2fa;color:#171821}html.dark .entry-chip{background:#20232f;border-color:#363949;color:#c8c9da}html.dark .entry-chip.active{background:#30345a;color:#c3c5ff}html.dark .work-pill{color:#d0d1df;background:color-mix(in srgb,var(--c,#777) 25%,#1a1c27)}html.dark .bar-value{color:#bfc1d4}html.dark .bars{border-color:#353746}html.dark .hero-card{background:#633e4f}html.dark .danger-card{background:#1a1c27;color:#f4f4fb;border-color:#303342}html.dark .danger-card p,html.dark .backup-card p{color:#aeb0c5}\n.formula-editor label.hidden{display:none!important}\n"""

# SW version
sw=(p/'sw.js').read_text().replace('earnings-pwa-v14','earnings-pwa-v15')

(p/'app.js').write_text(app)
(p/'index.html').write_text(html)
(p/'styles.css').write_text(css)
(p/'sw.js').write_text(sw)
